import type { LayoutConfig, LayoutPreset } from "./types";

export type LayoutDirs = { apps: string; packages: string };

/** Official presets only choose the convention directories. */
export const LAYOUT_PRESET_DIRS = {
  standard: { apps: "apps", packages: "packages" },
  libs: { apps: "apps", packages: "libs" },
} as const satisfies Record<LayoutPreset, LayoutDirs>;

/**
 * Integration packages generated by catalog providers. They are not part of the
 * layout schema (any slug id is accepted there); they are listed so expansion
 * and workspace tooling know their default location.
 */
export const LAYOUT_INTEGRATION_PACKAGE_IDS = ["arara", "notifique", "millionsend"] as const;

export const standardLayout = { version: 1, preset: "standard" } satisfies LayoutConfig;
export const libsLayout = { version: 1, preset: "libs" } satisfies LayoutConfig;

/** @deprecated Use `standardLayout` with `apps: { web: "apps/client" }`. */
export const serverSeparatedLayout = {
  version: 1,
  preset: "standard",
  apps: { web: "apps/client" },
} satisfies LayoutConfig;

export const LAYOUT_PRESETS = {
  standard: standardLayout,
  libs: libsLayout,
} as const satisfies Record<LayoutPreset, LayoutConfig>;
